import { test, expect } from '@playwright/test';

test.describe('Bottom Sheet Replacement for Dropdowns on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display bottom sheet when dropdown is clicked on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 862 });

    // Verify dropdown button is visible
    const dropdownButton = page.getByRole('button', { name: /select option/i });
    await expect(dropdownButton).toBeVisible();

    // Click dropdown button
    await dropdownButton.click();

    // Verify bottom sheet appears
    const bottomSheet = page.getByRole('dialog', { name: /select option/i });
    await expect(bottomSheet).toBeVisible();

    // Verify options are displayed in bottom sheet
    const option1 = page.getByRole('option', { name: /option one/i });
    const option2 = page.getByRole('option', { name: /option two/i });
    await expect(option1).toBeVisible();
    await expect(option2).toBeVisible();

    // Select option 1
    await option1.click();

    // Verify bottom sheet closes
    await expect(bottomSheet).not.toBeVisible();

    // Verify selected value is displayed in dropdown
    await expect(dropdownButton).toContainText('Option One');
  });

  test('should handle bottom sheet closing via escape key and selecting option', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 860 });

    // Click dropdown button to open bottom sheet
    const dropdownButton = page.getByRole('button', { name: /select option/i });
    await dropdownButton.click();

    // Verify bottom sheet is visible
    const bottomSheet = page.getByRole('dialog', { name: /select option/i });
    await expect(bottomSheet).toBeVisible();

    // Close bottom sheet using escape key
    await page.keyboard.press('Escape');

    // Verify bottom sheet is closed
    await expect(bottomSheet).not.toBeVisible();

    // Reopen bottom sheet
    await dropdownButton.click();
    await expect(bottomSheet).toBeVisible();

    // Select option 2
    const optionTwo = page.getByRole('option', { name: /option two/i });
    await optionTwo.click();

    // Verify bottom sheet closes
    await expect(bottomSheet).not.toBeVisible();

    // Verify selected value is displayed
    await expect(dropdownButton).toContainText('Option Two');
  });
});
